import json

def mask_sensitive_headers(headers: dict) -> dict:
    sensitive_headers = ['Authorization', 'Cookie']
    return {k: (v if k not in sensitive_headers else '[REDACTED]') for k, v in headers.items()}

def mask_body(body: str) -> str:
    # Пример маскировки: заменяем все значения в JSON на '[REDACTED]'
    try:
        body_dict = json.loads(body)
        return json.dumps({k: '[REDACTED]' for k in body_dict.keys()})
    except json.JSONDecodeError:
        return '[REDACTED]'

def format_request_log(method: str, path: str, headers: dict, body: str) -> str:
    masked_headers = mask_sensitive_headers(headers)
    masked_body = mask_body(body)
    return f"Method: {method}, Path: {path}, Headers: {masked_headers}, Body: {masked_body}"

